//! Tests of the key session and of key export/import (GitHub #1020).
//!
//! Methodology, for every test below: keys are generated by
//! [`keystore::generate`] (real argon2id + AES-256-GCM + ed25519, no mocks)
//! and saved to temporary keystores standing in for two machines' config
//! dirs; stamps are signed over the real signed bytes and judged with
//! [`Registry::build`] + [`verify_review`] against an in-memory
//! `kovan_root.toml` ([`ReviewRoot`]). The auto-lock runs on a
//! [`SessionClock::Manual`] clock, moved by hand, so no test sleeps. Pass
//! criterion: the exact typed result (verified / [`KeystoreError`]
//! variant) the rule in `session.rs` and `Keystore::{export, import}`
//! predicts.
//!
//! Result (2026-10-22): all pass (`cargo test --release -p kovan-common
//! --lib session_tests`).

use std::path::Path;
use std::time::Duration;

use super::keystore::{self, KeyFile, Keystore, KeystoreError};
use super::registry::Registry;
use super::session::{
    ensure_unlocked, with_session_key, KeySession, SessionClock, SharedKeySession, DEFAULT_AUTO_LOCK,
};
use super::tests::{person, root, signed, ALICE, F, FOUNDER, PASS};
use super::verify_review;
use crate::review::root::{ReviewRoot, Role};

fn new_key(ks: &Keystore, reviewer: &str, id: &str) -> KeyFile {
    let (file, _) = keystore::generate(reviewer, id, "2026-10-07", PASS).unwrap();
    ks.save(&file).unwrap();
    file
}

fn registry_of(files: &[&KeyFile]) -> ReviewRoot {
    root(
        files
            .iter()
            .map(|f| person(&f.reviewer, Role::Maintainer, vec![f.reviewer_key()]))
            .collect(),
    )
}

fn sign_with(s: &SharedKeySession, file: &KeyFile, pass: &str) -> Result<super::ReviewEntry, KeystoreError> {
    with_session_key(s, file, pass, |k| signed(k, F, "2026-10-07"))
}

/// One unlock signs two stamps; both verify against the registry. While
/// held, the session reports the key (reviewer, id, fingerprint, time
/// left) and `Debug` prints no secret. A wrong passphrase while locked
/// leaves the session locked.
#[test]
fn one_unlock_signs_two_stamps() {
    let dir = tempfile::tempdir().unwrap();
    let ks = Keystore::at(dir.path());
    let file = new_key(&ks, FOUNDER, "k1");
    let reg = Registry::build(&registry_of(&[&file]));
    let clock = SessionClock::manual();
    let s = KeySession::shared(DEFAULT_AUTO_LOCK, clock.clone());

    assert_eq!(sign_with(&s, &file, "").unwrap_err(), KeystoreError::Locked);
    assert_eq!(sign_with(&s, &file, "wrong").unwrap_err(), KeystoreError::WrongPassphrase);
    assert!(s.read().unwrap().status().is_none());

    let first = sign_with(&s, &file, PASS).unwrap();
    clock.advance(Duration::from_secs(60));
    let second = sign_with(&s, &file, "").unwrap();
    assert!(verify_review(&first, &reg).is_verified());
    assert!(verify_review(&second, &reg).is_verified());

    let st = s.read().unwrap().status().unwrap();
    assert_eq!((st.reviewer.as_str(), st.key.as_str()), (FOUNDER, "k1"));
    assert_eq!(st.fingerprint, file.fingerprint().unwrap());
    assert_eq!(st.locks_in, DEFAULT_AUTO_LOCK, "the second signing restarted the idle clock");
    assert!(s.read().unwrap().holds(FOUNDER, "k1"));
    assert!(!s.read().unwrap().holds(FOUNDER, "k2"));
    let dbg = format!("{:?}", s.read().unwrap());
    assert!(dbg.contains(FOUNDER) && !dbg.contains(&file.cipher.ciphertext));
    // Already held: ensure_unlocked needs no passphrase.
    assert_eq!(ensure_unlocked(&s, &file, ""), Ok(()));
}

/// The auto-lock: still unlocked 1 s before the timeout (and that use
/// restarts the clock); locked once the timeout passes without use, after
/// which the next signing asks again. `set_auto_lock` applies to the held
/// key; the system clock ignores `advance`.
#[test]
fn auto_lock_after_the_timeout() {
    let dir = tempfile::tempdir().unwrap();
    let ks = Keystore::at(dir.path());
    let file = new_key(&ks, FOUNDER, "k1");
    let clock = SessionClock::manual();
    let s = KeySession::shared(Duration::from_secs(600), clock.clone());
    assert_eq!(s.read().unwrap().auto_lock(), Duration::from_secs(600));
    sign_with(&s, &file, PASS).unwrap();

    clock.advance(Duration::from_secs(599));
    assert_eq!(s.read().unwrap().status().unwrap().locks_in, Duration::from_secs(1));
    sign_with(&s, &file, "").unwrap();
    clock.advance(Duration::from_secs(599));
    assert!(s.read().unwrap().holds(FOUNDER, "k1"), "the use restarted the clock");

    clock.advance(Duration::from_secs(1));
    assert!(!s.read().unwrap().holds(FOUNDER, "k1"));
    assert!(s.read().unwrap().status().is_none());
    assert!(s.write().unwrap().expire_if_idle(), "dropped now");
    assert!(!s.write().unwrap().expire_if_idle(), "nothing left to drop");
    assert_eq!(sign_with(&s, &file, "").unwrap_err(), KeystoreError::Locked);
    sign_with(&s, &file, PASS).unwrap();

    s.write().unwrap().set_auto_lock(Duration::from_secs(5));
    clock.advance(Duration::from_secs(5));
    assert_eq!(sign_with(&s, &file, "").unwrap_err(), KeystoreError::Locked);

    let sys = SessionClock::default();
    let before = sys.now();
    sys.advance(Duration::from_secs(3600));
    assert!(sys.now().duration_since(before) < Duration::from_secs(3600));
    assert_eq!(KeySession::default().auto_lock(), DEFAULT_AUTO_LOCK);
}

/// "Lock now": the next signing asks for the passphrase again. Another
/// key is not the held one (it asks too), and unlocking it replaces the
/// first. A key file whose public key differs from the held key's (same
/// reviewer and id) is not served by the held key.
#[test]
fn lock_now_and_other_keys_ask_again() {
    let dir = tempfile::tempdir().unwrap();
    let ks = Keystore::at(dir.path());
    let file = new_key(&ks, FOUNDER, "k1");
    let other = new_key(&ks, FOUNDER, "k2");
    let s = KeySession::shared(DEFAULT_AUTO_LOCK, SessionClock::manual());
    sign_with(&s, &file, PASS).unwrap();
    assert!(s.write().unwrap().lock());
    assert!(!s.write().unwrap().lock(), "already locked");
    assert_eq!(sign_with(&s, &file, "").unwrap_err(), KeystoreError::Locked);

    sign_with(&s, &file, PASS).unwrap();
    assert_eq!(sign_with(&s, &other, "").unwrap_err(), KeystoreError::Locked);
    sign_with(&s, &other, PASS).unwrap();
    assert!(s.read().unwrap().holds(FOUNDER, "k2"));
    assert!(!s.read().unwrap().holds(FOUNDER, "k1"), "one key at a time");

    let (lookalike, _) = keystore::generate(FOUNDER, "k2", "2026-10-07", PASS).unwrap();
    assert_eq!(sign_with(&s, &lookalike, "").unwrap_err(), KeystoreError::Locked);
}

/// Export on machine A, import on a fresh machine B (another config dir):
/// the exported file is byte-identical to A's key file, B's copy too; the
/// public key and fingerprint are the same on both sides; and a stamp
/// signed with the key unlocked on B verifies against the registry entry
/// A's key already has (nothing new to endorse). A second import of the
/// same file is `already_present` and writes nothing.
#[test]
fn export_then_import_on_a_fresh_machine() {
    let a = tempfile::tempdir().unwrap();
    let b = tempfile::tempdir().unwrap();
    let carry = tempfile::tempdir().unwrap();
    let ks_a = Keystore::at(a.path().join("keys"));
    let ks_b = Keystore::at(b.path().join("keys"));
    let file = new_key(&ks_a, FOUNDER, "k1");
    let reg_root = registry_of(&[&file]);

    let dest = carry.path().join("founder-k1.kovankey");
    let ex = ks_a.export(FOUNDER, "k1", &dest).unwrap();
    assert_eq!((ex.path.as_path(), ex.reviewer.as_str(), ex.key.as_str()), (dest.as_path(), FOUNDER, "k1"));
    let original = std::fs::read(ks_a.path_for(FOUNDER, "k1")).unwrap();
    assert_eq!(std::fs::read(&dest).unwrap(), original);
    assert!(matches!(ks_a.export(FOUNDER, "k1", &dest), Err(KeystoreError::AlreadyExists(_))));
    assert!(matches!(ks_a.export(FOUNDER, "k9", &carry.path().join("x")), Err(KeystoreError::Io { .. })));

    let (im, key_b) = ks_b.import(&dest, PASS, &reg_root).unwrap();
    assert!(!im.already_present);
    assert_eq!(im.path, ks_b.path_for(FOUNDER, "k1"));
    assert_eq!(std::fs::read(&im.path).unwrap(), original);
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt as _;
        assert_eq!(std::fs::metadata(&im.path).unwrap().permissions().mode() & 0o777, 0o600);
    }
    assert_eq!(key_b.public_b64(), file.public);
    assert_eq!(ex.fingerprint, im.fingerprint);
    assert_eq!(key_b.fingerprint(), im.fingerprint);
    assert_eq!(ks_b.load(FOUNDER, "k1").unwrap(), file);
    assert!(im.fingerprint.starts_with("SHA256:") && im.fingerprint.len() == 7 + 43);

    let reg = Registry::build(&reg_root);
    assert!(verify_review(&signed(&key_b, F, "2026-10-07"), &reg).is_verified());

    let (again, _) = ks_b.import(&dest, PASS, &reg_root).unwrap();
    assert!(again.already_present);
    assert_eq!(std::fs::read(&im.path).unwrap(), original);
}

/// The import refusals, each with nothing written: a tampered header (AAD
/// mismatch, reported as wrong passphrase or altered file); a key the
/// registry does not list, with a message naming the key, its fingerprint
/// and what to do; a different key already under that file name (the clash,
/// the existing file kept byte for byte); a file of that name that is not
/// a key file; a wrong passphrase; another format; a missing source.
#[test]
fn import_refusals() {
    let a = tempfile::tempdir().unwrap();
    let b = tempfile::tempdir().unwrap();
    let ks_a = Keystore::at(a.path().join("keys"));
    let ks_b = Keystore::at(b.path().join("keys"));
    let file = new_key(&ks_a, FOUNDER, "k1");
    let reg_root = registry_of(&[&file]);
    let dest = a.path().join("export.kovankey");
    ks_a.export(FOUNDER, "k1", &dest).unwrap();
    let text = std::fs::read_to_string(&dest).unwrap();
    let nothing_in_b = |ks: &Keystore| assert_eq!(ks.list().unwrap(), vec![]);

    // Tampered header: the date edited; the AAD no longer matches.
    let tampered = a.path().join("tampered.kovankey");
    std::fs::write(&tampered, text.replace("2026-10-07", "2026-10-08")).unwrap();
    assert_eq!(ks_b.import(&tampered, PASS, &reg_root).unwrap_err(), KeystoreError::WrongPassphrase);
    nothing_in_b(&ks_b);

    // Not in the registry: an empty one, then Alice's key only.
    let e = ks_b.import(&dest, PASS, &root(vec![])).unwrap_err();
    assert_eq!(
        e,
        KeystoreError::NotRegistered {
            reviewer: FOUNDER.into(),
            key: "k1".into(),
            fingerprint: file.fingerprint().unwrap(),
        }
    );
    let msg = e.to_string();
    assert!(msg.contains(FOUNDER) && msg.contains("not in this workspace's kovan_root.toml"), "{msg}");
    assert!(msg.contains(&file.fingerprint().unwrap()));
    let alice = new_key(&ks_a, ALICE, "a1");
    assert!(matches!(
        ks_b.import(&dest, PASS, &registry_of(&[&alice])),
        Err(KeystoreError::NotRegistered { .. })
    ));
    nothing_in_b(&ks_b);

    // Wrong passphrase, another format, a missing file.
    assert_eq!(ks_b.import(&dest, "wrong", &reg_root).unwrap_err(), KeystoreError::WrongPassphrase);
    let v0 = a.path().join("v0.kovankey");
    std::fs::write(&v0, text.replace(keystore::KEY_FILE_FORMAT, "kovan-ed25519-key-v0")).unwrap();
    assert!(matches!(ks_b.import(&v0, PASS, &reg_root), Err(KeystoreError::Unsupported(_))));
    let junk = a.path().join("junk.kovankey");
    std::fs::write(&junk, "not toml [").unwrap();
    assert!(matches!(ks_b.import(&junk, PASS, &reg_root), Err(KeystoreError::Parse { path: Some(_), .. })));
    assert!(matches!(ks_b.import(&a.path().join("none"), PASS, &reg_root), Err(KeystoreError::Io { .. })));
    nothing_in_b(&ks_b);

    // A clash: machine B made its own k1 before the import.
    let own = new_key(&ks_b, FOUNDER, "k1");
    let before = std::fs::read(ks_b.path_for(FOUNDER, "k1")).unwrap();
    let e = ks_b.import(&dest, PASS, &reg_root).unwrap_err();
    assert_eq!(e, KeystoreError::Clash { path: ks_b.path_for(FOUNDER, "k1") });
    assert!(e.to_string().contains("nothing was overwritten"));
    assert_eq!(std::fs::read(ks_b.path_for(FOUNDER, "k1")).unwrap(), before);
    assert_eq!(ks_b.load(FOUNDER, "k1").unwrap(), own);

    // A non-key file under that name is not replaced either.
    let c = tempfile::tempdir().unwrap();
    let ks_c = Keystore::at(c.path());
    std::fs::write(ks_c.path_for(FOUNDER, "k1"), "not a key").unwrap();
    assert!(matches!(ks_c.import(&dest, PASS, &reg_root), Err(KeystoreError::Clash { .. })));
    assert_eq!(std::fs::read_to_string(ks_c.path_for(FOUNDER, "k1")).unwrap(), "not a key");

    // The new errors say something, and a bad public key has no fingerprint.
    assert!(!KeystoreError::Locked.to_string().is_empty());
    assert_eq!(keystore::fingerprint("!!").unwrap_err(), KeystoreError::BadField("public".into()));
}

fn files_under(dir: &Path, out: &mut Vec<std::path::PathBuf>) {
    for e in std::fs::read_dir(dir).unwrap() {
        let p = e.unwrap().path();
        if p.is_dir() {
            files_under(&p, out);
        } else {
            out.push(p);
        }
    }
}

fn contains(hay: &[u8], needle: &[u8]) -> bool {
    hay.windows(needle.len()).any(|w| w == needle)
}

/// No new plaintext key material on disk: after a whole session (generate
/// and save, unlock, sign twice, lock, auto-lock, export, import on a
/// second config dir), no file under either config dir or the export folder
/// holds the secret seed (raw, base64 or hex) or the passphrase.
#[test]
fn no_plaintext_key_material_on_disk_after_a_session() {
    let a = tempfile::tempdir().unwrap();
    let b = tempfile::tempdir().unwrap();
    let ks_a = Keystore::at(a.path().join("keys"));
    let ks_b = Keystore::at(b.path().join("keys"));
    let (file, generated) = keystore::generate(FOUNDER, "k1", "2026-10-07", PASS).unwrap();
    ks_a.save(&file).unwrap();
    let seed = generated.seed_for_tests();
    drop(generated);
    let reg_root = registry_of(&[&file]);

    let clock = SessionClock::manual();
    let s = KeySession::shared(Duration::from_secs(60), clock.clone());
    sign_with(&s, &file, PASS).unwrap();
    sign_with(&s, &file, "").unwrap();
    s.write().unwrap().lock();
    sign_with(&s, &file, PASS).unwrap();
    clock.advance(Duration::from_secs(60));
    s.write().unwrap().expire_if_idle();
    let dest = a.path().join("export").join("k1.kovankey");
    std::fs::create_dir_all(dest.parent().unwrap()).unwrap();
    ks_a.export(FOUNDER, "k1", &dest).unwrap();
    let (_, key_b) = ks_b.import(&dest, PASS, &reg_root).unwrap();
    s.write().unwrap().hold(key_b);
    sign_with(&s, &file, "").unwrap();

    let b64 = base64::Engine::encode(&base64::engine::general_purpose::STANDARD, seed);
    let b64_np = base64::Engine::encode(&base64::engine::general_purpose::STANDARD_NO_PAD, seed);
    let hex: String = seed.iter().map(|x| format!("{x:02x}")).collect();
    let mut files = Vec::new();
    files_under(a.path(), &mut files);
    files_under(b.path(), &mut files);
    assert_eq!(files.len(), 3, "{files:?}");
    for f in &files {
        let bytes = std::fs::read(f).unwrap();
        for needle in [&seed[..], b64.as_bytes(), b64_np.as_bytes(), hex.as_bytes(), PASS.as_bytes()] {
            assert!(!contains(&bytes, needle), "{} holds secret material", f.display());
        }
    }
}
